using System.Buffers;
using ZeroAlloc.Serialisation;

namespace ZeroAlloc.Scheduling;

/// <summary>
/// AOT-safe <see cref="IJobSerializer"/> implementation that delegates to an
/// <see cref="ISerializerDispatcher"/> generated by <c>ZeroAlloc.Serialisation</c>.
/// </summary>
/// <remarks>
/// Register by annotating your job types with <c>[ZeroAllocSerializable]</c> in the
/// consuming assembly and calling <c>services.AddSerializerDispatcher()</c>, before or after
/// <c>AddScheduling()</c>. <c>AddScheduling</c> then resolves <see cref="IJobSerializer"/> to this
/// class. It is the trim- and AOT-safe choice; the reflection-based
/// <see cref="SystemTextJsonJobSerializer"/> is used only when the application opts in with
/// <c>WithSystemTextJsonSerializer()</c>.
/// </remarks>
public sealed class DispatchingJobSerializer : IJobSerializer
{
    private readonly ISerializerDispatcher _dispatcher;

    /// <summary>Initializes a new <see cref="DispatchingJobSerializer"/>.</summary>
    public DispatchingJobSerializer(ISerializerDispatcher dispatcher)
    {
        _dispatcher = dispatcher ?? throw new ArgumentNullException(nameof(dispatcher));
    }

    /// <summary>
    /// A writer that grew past this many bytes is dropped after the call instead of being kept for the
    /// thread, so one unusually large payload does not pin its buffer for the life of the thread.
    /// </summary>
    private const int MaxRetainedCapacity = 64 * 1024;

    // One buffer writer per thread, reused across calls. Serialize empties the slot while it writes,
    // so a reentrant call on the same thread, for example from a custom converter, uses a writer of
    // its own instead of appending to the outer call's bytes.
    [ThreadStatic]
    private static ArrayBufferWriter<byte>? t_writer;

    /// <inheritdoc/>
    /// <remarks>
    /// The dispatcher writes the payload into a buffer writer reused by the calling thread, through
    /// <see cref="ISerializerDispatcher.Serialize{T}(IBufferWriter{byte}, T)"/>, which does not box a
    /// struct job. The bytes are then copied once into the exact-size array the store persists, so that
    /// array is the only allocation on top of what the format's serializer itself allocates.
    /// </remarks>
    public byte[] Serialize<T>(T job) where T : notnull
    {
        var writer = t_writer ?? new ArrayBufferWriter<byte>();
        t_writer = null;
        try
        {
            _dispatcher.Serialize(writer, job);
            return writer.WrittenSpan.ToArray();
        }
        finally
        {
            if (writer.Capacity <= MaxRetainedCapacity)
            {
                writer.ResetWrittenCount();
                t_writer = writer;
            }
        }
    }

    /// <inheritdoc/>
    /// <remarks>
    /// Reads through <see cref="ISerializerDispatcher.Deserialize{T}(ReadOnlyMemory{byte})"/>, which returns a
    /// struct job as itself instead of boxing it. A null result, or a result that is not a
    /// <typeparamref name="T"/>, throws <see cref="InvalidOperationException"/>.
    /// </remarks>
    public T Deserialize<T>(byte[] payload) where T : notnull
    {
        T? result;
        try
        {
            result = _dispatcher.Deserialize<T>(new ReadOnlyMemory<byte>(payload));
        }
        catch (InvalidCastException ex)
        {
            // The interface's default implementation, used by a dispatcher written by hand, unboxes the
            // object-returning read and throws this when that returned another type.
            throw WrongResult<T>(ex);
        }

        return result is T typed ? typed : throw WrongResult<T>(inner: null);
    }

    private static InvalidOperationException WrongResult<T>(Exception? inner)
        => new($"Deserializing {typeof(T).Name} returned null or wrong type.", inner);
}
